def threeSum(nums):
    nums.sort()
    ans = []
    n = len(nums)
    for i in range(n):
        if i and nums[i] == nums[i - 1]:
            continue            # 跳过重复的三元组
        l, r = i + 1, n - 1
        while l < r:
            s = nums[i] + nums[l] + nums[r]
            if s < 0:
                l += 1
            elif s > 0:
                r -= 1
            else:
                ans.append([nums[i], nums[l], nums[r]])
                l += 1
                r -= 1
                while l < r and nums[l] == nums[l - 1]:
                    l += 1      # 跳过重复的左数
                while l < r and nums[r] == nums[r + 1]:
                    r -= 1      # 跳过重复的右数
    return ans

