from collections import deque

def maxSlidingWindow(nums, k):
    dq = deque()       # 存下标，对应值单调递减
    ans = []
    for i, x in enumerate(nums):
        while dq and nums[dq[-1]] < x:
            dq.pop()   # 比 x 小又靠左，不可能是最大值
        dq.append(i)
        if dq[0] <= i - k:
            dq.popleft()  # 队头滑出窗口
        if i >= k - 1:
            ans.append(nums[dq[0]])
    return ans

