def detectCycle(head):
    slow = fast = head
    # 第一阶段：快慢指针找相遇点
    while fast and fast.next:
        slow = slow.next          # 慢指针走 1 步
        fast = fast.next.next     # 快指针走 2 步
        if slow is fast:
            break
    else:
        return None               # 无环
    # 第二阶段：一个指针回头部，同速走
    slow = head
    while slow is not fast:
        slow = slow.next
        fast = fast.next
    return slow                   # 环的入口

