def numIslands(grid):
    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '1':
                count += 1
                dfs(grid, i, j)   # 把整座岛染成 '0'
    return count

def dfs(g, i, j):
    if (i < 0 or i >= len(g) or j < 0 or j >= len(g[0])
            or g[i][j] != '1'):
        return
    g[i][j] = '0'                 # 染色 = 标记访问过
    dfs(g, i + 1, j)
    dfs(g, i - 1, j)
    dfs(g, i, j + 1)
    dfs(g, i, j - 1)

