def permute(nums):
    ans = []
    def dfs(path, used):
        if len(path) == len(nums):
            ans.append(path.copy())   # 到底了，收一个排列
            return
        for i in range(len(nums)):
            if used[i]:
                continue
            used[i] = True            # 做选择
            path.append(nums[i])
            dfs(path, used)
            path.pop()                # 撤销选择
            used[i] = False
    dfs([], [False] * len(nums))
    return ans

