def minDistance(w1, w2):
    m, n = len(w1), len(w2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i            # w1 前 i 个全删
    for j in range(n + 1):
        dp[0][j] = j            # 全插成 w2 前 j 个
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if w1[i - 1] == w2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # 相同白嫖
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],      # 删
                    dp[i][j - 1],      # 插
                    dp[i - 1][j - 1])  # 换
    return dp[m][n]

