import torch

def sample(logits, temperature, u):
    p = torch.softmax(logits / temperature, dim=-1)
    cum = 0.0
    for i, pi in enumerate(p):
        cum += pi
        if u < cum:
            return i          # 按累积分布采样
    return len(p) - 1

